/**
 * External plugin registry
 *
 * These plugins were developed in separate repositories and are bundled with the SDK.
 * Order matters: earlier plugins have precedence during build and transform.
 *
 * Keep this file free of external imports — it is loaded by esbuild.external-plugins.ts
 * during the prebuild step, before workspace packages are compiled.
 */
/** SDK subpaths where external plugin APIs can be exposed */
export type SdkExportPath = 'core' | 'automation';
export interface ExternalPlugin {
    /** npm package name */
    packageName: string;
    /** Short, filesystem-safe identifier used for directory names and TypeScript exports.
     *  Must be unique across all registered plugin packages. */
    slug: string;
    /** SDK subpath where the API should be exposed (e.g., '@servicenow/sdk/core' or '@servicenow/sdk/automation').
     *  Defaults to 'core'. */
    sdkExportPath?: SdkExportPath;
    /** When true, `plugins:sync` auto-generates TableOwnership entries in record-plugin.ts
     *  from `@table` JSDoc tags in the plugin's synced API files.
     *
     *  Opt-in because some plugins may have hand-maintained TableOwnership entries that
     *  don't align 1:1 with their @table tags — enabling this rewrites those entries.
     *  May become the default in a future version. */
    syncTableOwnership?: boolean;
}
export declare const EXTERNAL_PLUGINS: readonly ExternalPlugin[];
